package httpserver

import (
	"html/template"
	"io"
	"net/http"
)

func (s *Server) index(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	page := template.Must(template.New("evidence-demo").Parse(evidenceDemoPage))
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_ = page.Execute(w, map[string]string{"Provider": s.provider.Name()})
}

func evidenceDemoScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, evidenceDemoJavaScript)
}

const evidenceDemoPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文件与证据</title><style>` + evidenceDemoCSS + `</style></head><body><header><a href="/" class="brand"><b>EV</b><strong>文件与证据</strong></a><div><span class="provider">存储：{{.Provider}}</span><span id="authState">尚未连接</span><button id="authButton" class="secondary">设置访问凭证</button></div></header><div class="app"><nav><small>Evidence Service</small><button class="nav active" data-page="overview">概览</button><button class="nav" data-page="files">文件库</button><p><strong>边界说明</strong>业务应用只保存 File ID / Version 与业务含义；密钥、对象路径和物理清理由本服务拥有。</p></nav><main>
<section id="overview" class="page active"><div class="hero"><p class="kicker">File Facts</p><h1>一次上传，留下可以被业务长期引用的证据。</h1><p>创建有时效的上传会话，文件直传本地存储或 OSS；服务端完成大小、摘要和状态校验，再签发短期访问地址。</p><button class="primary" data-open="files">打开文件库</button></div><div class="steps"><article><b>01</b><h2>创建会话</h2><p>声明文件名、类型、大小和用途，获得短期有界授权。</p></article><article><b>02</b><h2>直传并校验</h2><p>文件不经过业务应用；完成时验证大小与 SHA-256。</p></article><article><b>03</b><h2>按 ID 引用</h2><p>下游只持有稳定 File ID / Version，需要时申请短期链接。</p></article></div></section>
<section id="files" class="page"><div class="title"><div><p class="kicker">Evidence Library</p><h1>文件库</h1></div><button id="refresh" class="secondary">刷新</button></div><div id="notice" class="notice">设置访问凭证后读取文件版本。</div><div class="columns"><section class="panel"><div class="panel-title"><h2>可用文件</h2><button id="newUpload" class="primary">上传文件</button></div><div id="fileList" class="list"><div class="empty">尚未读取数据。</div></div></section><section class="panel workspace"><div id="blank" class="empty focus"><strong>选择一个文件</strong><span>查看文件事实，或申请短期访问地址。</span></div><div id="details" hidden><div class="file-head"><div><span id="fileStatus" class="pill"></span><h2 id="fileName"></h2><code id="fileID"></code></div><div class="file-actions"><button id="newVersion" class="secondary">上传新版本</button><button id="getAccess" class="primary">查看 / 下载</button></div></div><dl><div><dt>版本</dt><dd id="version"></dd></div><div><dt>大小</dt><dd id="size"></dd></div><div><dt>媒体类型</dt><dd id="media"></dd></div></dl><section class="digest"><span>SHA-256</span><code id="sha"></code></section><aside><strong>为什么是短期地址？</strong><p>页面不持有 OSS 长期密钥；访问授权到期后必须重新申请，业务引用的 File ID 不变。</p></aside></div></section></div></section></main></div>
<dialog id="authDialog"><form id="authForm" method="dialog"><p class="kicker">访问控制</p><h2>连接业务 API</h2><p>粘贴本地模板 Token 或 IAM 短期 Capability Credential。只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><footer><button value="cancel" class="secondary">取消</button><button class="primary">保存并连接</button></footer></form></dialog>
<dialog id="uploadDialog"><form id="uploadForm" method="dialog"><p class="kicker">受控上传</p><h2 id="uploadTitle">上传一份文件</h2><p id="uploadHint">浏览器会先计算摘要，再请求短期上传授权。页面不会保存 STS 凭证。</p><label>选择文件<input id="fileInput" name="file" type="file" required></label><label>业务用途<input name="purpose" value="demo-evidence" required></label><label>业务引用<input name="owner_ref" placeholder="例如 contract:UUID"></label><div id="progress" class="progress">等待选择文件</div><footer><button value="cancel" class="secondary">取消</button><button id="uploadButton" class="primary">计算摘要并上传</button></footer></form></dialog><script src="/assets/demo.js"></script></body></html>`

const evidenceDemoCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",system-ui,sans-serif;color:#182235;background:#f4f5f7;--muted:#667085;--line:#d9dee7;--soft:#f7f9fb;--accent:#215aa8;--nav:#15365f}*{box-sizing:border-box}body{margin:0}header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}header>div{display:flex;align-items:center;gap:11px;color:var(--muted);font-size:13px}.provider{padding:4px 8px;border-radius:99px;background:#edf3fb;color:#315477}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand b{display:grid;width:34px;height:34px;place-items:center;border-radius:7px;background:var(--nav);color:#fff;font-size:12px}.app{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 64px)}nav{padding:26px 18px;background:#fff;border-right:1px solid var(--line)}nav small,.kicker{display:block;margin:0 0 9px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{display:block;width:100%;padding:11px 13px;border:0;border-left:3px solid transparent;background:transparent;text-align:left;color:#4d596b;font:inherit;cursor:pointer}.nav.active{border-color:var(--accent);background:#edf3fb;color:var(--accent);font-weight:750}nav p{display:grid;gap:5px;margin-top:32px;padding:14px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}main{min-width:0;padding:30px}.page{display:none}.page.active{display:block}.hero{min-height:340px;padding:54px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#fff 65%,#e8eff8)}h1,h2,h3,p{margin-top:0}.hero h1{max-width:800px;margin-bottom:18px;font-size:clamp(34px,5vw,58px);line-height:1.07;letter-spacing:-.045em}.hero>p:not(.kicker){max-width:720px;color:var(--muted);font-size:17px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.steps article,.panel{padding:21px;border:1px solid var(--line);border-radius:10px;background:#fff}.steps b{color:var(--accent)}.steps h2{margin:12px 0 5px;font-size:17px}.steps p{margin:0;color:var(--muted);font-size:13px}.primary,.secondary{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.secondary{border-color:var(--line);background:#fff;color:#414c5d}.title,.panel-title,.file-head,.file-actions{display:flex;align-items:center;justify-content:space-between;gap:16px}.file-actions{justify-content:flex-end;gap:8px}.title{margin-bottom:18px}.title h1{margin:0}.notice{margin-bottom:14px;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#9f2d2d}.columns{display:grid;grid-template-columns:350px 1fr;gap:16px}.panel{min-height:600px}.panel-title h2{margin:0;font-size:17px}.list{display:grid;gap:7px;margin-top:14px}.record{display:grid;gap:3px;padding:12px;border:1px solid var(--line);border-radius:7px;background:#fff;text-align:left;cursor:pointer}.record.active,.record:hover{border-color:#7da3cf;background:#f2f6fb}.record span,.record small{color:var(--muted)}.empty{display:grid;gap:5px;padding:24px;color:var(--muted);font-size:13px;text-align:center}.focus{min-height:420px;place-content:center}.file-head{padding-bottom:16px;border-bottom:1px solid var(--line)}.file-head h2{margin:6px 0 3px}.file-head code{color:var(--muted);font-size:11px}.pill{display:inline-flex;padding:3px 8px;border-radius:99px;background:#e4f4ea;color:#18653f;font-size:11px;font-weight:800}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}dl div,.digest{padding:12px;border-radius:6px;background:var(--soft)}dt,.digest span{color:var(--muted);font-size:11px}dd{margin:3px 0 0;font-size:13px}.digest{display:grid;gap:5px}.digest code{overflow-wrap:anywhere;font-size:12px}aside{margin-top:16px;padding:16px;border-left:3px solid #7b9fc8;background:#f0f5fa}aside p{margin:5px 0 0;color:var(--muted);font-size:13px}dialog{width:min(550px,calc(100% - 32px));padding:25px;border:1px solid var(--line);border-radius:10px;box-shadow:0 24px 80px #15223833}dialog::backdrop{background:#14203699}dialog>form>p:not(.kicker){color:var(--muted);font-size:13px}label{display:grid;gap:5px;margin-top:12px;color:#4c5667;font-size:12px;font-weight:700}input,textarea{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;font:inherit}.progress{margin-top:14px;padding:10px;border-radius:6px;background:var(--soft);color:var(--muted);font-size:12px}dialog footer{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}@media(max-width:960px){.app{grid-template-columns:1fr}nav{display:flex;padding:10px 18px;border-right:0;border-bottom:1px solid var(--line)}nav small,nav p{display:none}.nav{width:auto}.columns{grid-template-columns:1fr}.panel{min-height:auto}}@media(max-width:640px){header{padding:0 15px}header>div>span{display:none}main{padding:18px}.hero{padding:28px}.steps,dl{grid-template-columns:1fr}.file-head{align-items:flex-start;flex-direction:column}.file-actions{width:100%}}`

const evidenceDemoJavaScript = `(()=>{'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],suiteBase=location.pathname.startsWith('/evidence/')?'/evidence':'',state={token:sessionStorage.getItem('evidence-demo-token')||'',items:[],selected:null,versionTarget:null};const uuid=()=>crypto.randomUUID();
function note(m,t=''){const n=$('#notice');n.textContent=m;n.className='notice '+t}function page(id){$$('.page').forEach(x=>x.classList.toggle('active',x.id===id));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id))}function bytes(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
async function api(path,opt={}){if(!suiteBase&&!state.token)throw new Error('请先设置访问凭证');const headers={...(opt.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;if(opt.body)headers['Content-Type']='application/json';const r=await fetch(suiteBase+path,{credentials:'same-origin',...opt,headers}),text=await r.text();let d={};try{d=text?JSON.parse(text):{}}catch{throw new Error(r.redirected?'需要从统一工作台重新进入应用':'服务返回内容无法识别')}if(!r.ok)throw new Error(d.error?.message||('请求失败 '+r.status));return d}
function record(x){const b=document.createElement('button');b.className='record'+(state.selected?.file_id===x.file_id&&state.selected?.version===x.version?' active':'');b.innerHTML='<strong></strong><span></span><small></small>';b.children[0].textContent=x.file_name;b.children[1].textContent=x.status+' · version '+x.version;b.children[2].textContent=bytes(x.size_bytes)+' · '+x.media_type;b.onclick=()=>select(x);return b}
function select(x){state.selected=x;$('#blank').hidden=true;$('#details').hidden=false;$('#fileStatus').textContent=x.status;$('#fileName').textContent=x.file_name;$('#fileID').textContent=x.file_id;$('#version').textContent=x.version;$('#size').textContent=bytes(x.size_bytes);$('#media').textContent=x.media_type;$('#sha').textContent=x.sha256;$('#fileList').replaceChildren(...state.items.map(record))}
async function load(){try{note('正在读取文件版本…');const d=await api('/v1/files?limit=50');state.items=d.items||[];const l=$('#fileList');l.replaceChildren();state.items.forEach(x=>l.append(record(x)));if(!l.children.length)l.innerHTML='<div class="empty">还没有可用文件。</div>';note('已读取 '+state.items.length+' 个文件版本。','ok')}catch(e){note(e.message,'error')}}
async function sha256(file){const data=await file.arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function base64(buffer){let s='';for(const b of new Uint8Array(buffer))s+=String.fromCharCode(b);return btoa(s)}
async function hmacSHA1(secret,text){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-1'},false,['sign']);return base64(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(text)))}
function objectURL(a){const endpoint=a.endpoint.replace(/^https?:\/\//,'').replace(/\/$/,'');return 'https://'+(a.endpoint_is_cname===true?'':a.bucket+'.')+endpoint+'/'+a.object_key.split('/').map(encodeURIComponent).join('/')}
async function putOSS(a,file){const date=new Date().toUTCString(),type=a.headers?.['Content-Type']||file.type||'application/octet-stream',ossHeaders={'x-oss-date':date,'x-oss-forbid-overwrite':'true','x-oss-security-token':a.security_token};const canonical=Object.keys(ossHeaders).sort().map(k=>k+':'+ossHeaders[k]+'\n').join(''),resource='/'+a.bucket+'/'+a.object_key,stringToSign='PUT\n\n'+type+'\n'+date+'\n'+canonical+resource,signature=await hmacSHA1(a.access_key_secret,stringToSign);const headers={'Content-Type':type,Authorization:'OSS '+a.access_key_id+':'+signature,...ossHeaders};const r=await fetch(objectURL(a),{method:'PUT',headers,body:file});if(!r.ok)throw new Error('OSS 上传失败 '+r.status);return (r.headers.get('ETag')||'').replaceAll('"','')}
async function upload(file,purpose,owner,fileID){const digest=await sha256(file);$('#progress').textContent='摘要完成，正在申请短期授权…';const path=fileID?'/v1/files/'+fileID+'/versions/upload-sessions':'/v1/upload-sessions',session=await api(path,{method:'POST',headers:{'Idempotency-Key':uuid()},body:JSON.stringify({file_name:file.name,size_bytes:file.size,media_type:file.type||'application/octet-stream',sha256:digest,client_context:{purpose,owner_ref:owner}})}),a=session.authorization;$('#progress').textContent='正在直传 '+a.provider+'…';let etag='';if(a.provider==='local-http'){const r=await fetch(a.upload_url,{method:a.method||'PUT',headers:a.headers||{},body:file});if(!r.ok)throw new Error('本地存储上传失败 '+r.status);etag=(r.headers.get('ETag')||'').replaceAll('"','')}else if(a.provider==='aliyun-oss'){etag=await putOSS(a,file)}else throw new Error('当前页面不支持存储提供者 '+a.provider);$('#progress').textContent='上传完成，正在进行服务端校验…';return api('/v1/upload-sessions/'+session.session_id+'/complete',{method:'POST',headers:{'Idempotency-Key':uuid()},body:JSON.stringify({observed_size_bytes:file.size,observed_sha256:digest,etag})})}
function openUpload(fileID){state.versionTarget=fileID||null;$('#uploadTitle').textContent=fileID?'上传新版本':'上传一份文件';$('#uploadHint').textContent=fileID?'新版本沿用稳定 File ID，并保留旧版本；Project 等消费方会观察到 revision 变化。':'浏览器会先计算摘要，再请求短期上传授权。页面不会保存 STS 凭证。';$('#progress').textContent='等待选择文件';$('#uploadDialog').showModal()}
$$('.nav').forEach(x=>x.onclick=()=>page(x.dataset.page));$$('[data-open]').forEach(x=>x.onclick=()=>page(x.dataset.open));$('#authButton').onclick=()=>{$('#token').value=state.token;$('#authDialog').showModal()};$('#authForm').onsubmit=e=>{e.preventDefault();state.token=$('#token').value.trim();sessionStorage.setItem('evidence-demo-token',state.token);$('#authDialog').close();$('#authState').textContent='凭证已保存在当前标签页';load()};$('#refresh').onclick=load;$('#newUpload').onclick=()=>openUpload(null);$('#newVersion').onclick=()=>state.selected&&openUpload(state.selected.file_id);
$('#uploadForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=$('#fileInput').files[0],target=state.versionTarget;if(!file)return;$('#uploadButton').disabled=true;try{const v=await upload(file,String(f.get('purpose')),String(f.get('owner_ref')),target);$('#uploadDialog').close();e.target.reset();state.versionTarget=null;await load();select(v);note(target?'新版本已上传；旧版本仍保持不可变。':'文件已上传并通过服务端校验。','ok')}catch(err){$('#progress').textContent=err.message;note(err.message,'error')}finally{$('#uploadButton').disabled=false}};
$('#getAccess').onclick=async()=>{try{const x=state.selected,g=await api('/v1/files/'+x.file_id+'/versions/'+x.version+'/access-grants',{method:'POST',body:JSON.stringify({disposition:'inline',delivery_mode:'direct',file_name:x.file_name})});window.open(g.url,'_blank','noopener')}catch(e){note(e.message,'error')}};if(suiteBase){$('#authState').textContent='Gateway / IAM 短期能力凭证';$('#authButton').hidden=true;load()}else if(state.token){$('#authState').textContent='凭证已保存在当前标签页';load()}})();`
